// --- Issue #1: the ball plows through bricks (no bounce) ---------------------
//
// Each case below was added first as a red test, then made green in neon.js:
// per-face, corner, push-out, neighbours, tunnelling.

test('#1 per-face: a top hit flips vy and leaves vx untouched', () => {
  const state = createState(1);
  const ball = state.ball;
  const brick = state.bricks[Math.floor(BRICK_COLS / 2)];

  // Straight down into the middle of a brick's top face.
  ball.x = brick.x + brick.w / 2;
  ball.y = brick.y - BALL_R + 4; // bottom edge 4 px inside the top face
  ball.vx = 10; // a small drift: must survive untouched
  ball.vy = 300;
  ball.px = ball.x;
  ball.py = ball.y - 8; // the ball came from above

  brickHit(ball, state.bricks);

  assert.equal(Math.sign(ball.vy), UP, 'vy flips toward the ceiling');
  assert.equal(ball.vx, 10, 'vx is left exactly as it was');
  assert.ok(!collides(ball, brick), 'ball is pushed out of the brick');
  assert.equal(ball.y, brick.y - BALL_R, 'ball rests just above the top face');
  assert.equal(brick.alive, false);
});

test('#1 per-face: a side hit flips vx and leaves vy untouched', () => {
  const state = createState(1);
  const ball = state.ball;
  const brick = state.bricks[Math.floor(BRICK_COLS / 2)];

  // Straight right into the middle of a brick's left face.
  ball.x = brick.x - BALL_R + 4; // right edge 4 px inside the left face
  ball.y = brick.y + brick.h / 2;
  ball.vx = 300;
  ball.vy = 15; // a small drift: must survive untouched
  ball.px = ball.x - 8;
  ball.py = ball.y;

  brickHit(ball, state.bricks);

  assert.ok(ball.vx < 0, 'vx flips toward the left wall');
  assert.equal(ball.vy, 15, 'vy is left exactly as it was');
  assert.ok(!collides(ball, brick), 'ball is pushed out of the brick');
  assert.equal(ball.x, brick.x - BALL_R, 'ball rests just left of the face');
  assert.equal(brick.alive, false);
});

test('#1 corner: equal penetrations flip both components', () => {
  const state = createState(1);
  const ball = state.ball;
  const brick = state.bricks[Math.floor(BRICK_COLS / 2)];

  // 45° approach into the brick's top-left corner: the ball's box overlaps
  // the brick by exactly the same amount on both axes at every sample.
  ball.x = brick.x + 3;
  ball.y = brick.y + 3;
  ball.vx = 300;
  ball.vy = 300;
  ball.px = brick.x - BALL_R; // box exactly touches the corner (no overlap)
  ball.py = brick.y - BALL_R;

  brickHit(ball, state.bricks);

  assert.ok(ball.vx < 0, 'vx flips on a diagonal hit');
  assert.ok(ball.vy < 0, 'vy flips on a diagonal hit');
  assert.ok(!collides(ball, brick), 'ball is pushed out of the corner');
  assert.equal(ball.x, brick.x - BALL_R);
  assert.equal(ball.y, brick.y - BALL_R);
  assert.equal(brick.alive, false);
});

test('#1 neighbours: a seam hit bounces exactly once (no double-flip)', () => {
  const state = createState(1);
  const ball = state.ball;
  const left = state.bricks[0];
  const right = state.bricks[1];

  // The 8 px grid gap is narrower than the 14 px ball: coming straight down
  // the seam, the ball overlaps BOTH bricks in the same pass.
  assert.equal(right.x - (left.x + left.w), BRICK_GAP);
  ball.x = (left.x + left.w + right.x) / 2; // dead center of the seam
  ball.y = left.y - BALL_R + 4; // bottom edge sunk into both bricks
  ball.vx = 0;
  ball.vy = 300;
  ball.px = ball.x;
  ball.py = left.y - BALL_R - 6; // came from above

  brickHit(ball, state.bricks);

  assert.equal(Math.sign(ball.vy), UP, 'vy flips exactly once (two flips cancel)');
  assert.equal(ball.vx, 0, 'vx untouched on a straight-down seam hit');
  assert.ok(!collides(ball, left) && !collides(ball, right), 'ball pushed out of both bricks');
  assert.equal(left.alive, false);
  assert.equal(right.alive, false);
});

test('#1 tunnelling: a fast ball cannot skip a brick inside one capped frame', () => {
  const state = createState(6);
  const ball = state.ball;
  const brick = state.bricks[Math.floor(BRICK_COLS / 2)];

  // Level 6: ballSpeed(6) = 710 px/s. A stuttered frame capped at 50 ms moves
  // the ball 35.5 px, more than the 34 px (BRICK_H + diameter) it takes to
  // cross a brick: a single discrete test lands the ball beyond it.
  ball.x = brick.x + brick.w / 2;
  ball.y = brick.y - BALL_R - 1; // just above the brick, not touching
  ball.vx = 0;
  ball.vy = ballSpeed(6);
  const before = ball.y;

  step(state, 0.05);

  assert.ok(
    ball.y - before > BRICK_H + 2 * BALL_R,
    'precondition: the 50 ms step really jumps past the brick'
  );
  assert.ok(!collides(ball, brick), 'precondition: the naive test would miss it');

  brickHit(ball, state.bricks);

  assert.equal(Math.sign(ball.vy), UP, 'the sweep catches the brick: vy flips');
  assert.equal(brick.alive, false, 'the brick is destroyed');
  assert.ok(!collides(ball, brick), 'ball pushed out above the brick');
});

test('#1: a ball clear of the bricks is untouched', () => {
  const state = createState(1);
  const ball = state.ball;
  const { vx, vy } = ball;
  ball.y = 400; // well below the grid

  const broken = brickHit(ball, state.bricks);

  assert.equal(broken.length, 0);
  assert.equal(ball.vx, vx);
  assert.equal(ball.vy, vy);
  assert.ok(state.bricks.every((b) => b.alive));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).

