edits.newText:
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball was before this move: brickHit() sweeps the path
  // between the two positions to catch fast balls (tunnelling, see #1).
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

