// Face detection: for each touched brick, the smaller penetration is the
// face that was hit. Equal penetration on both axes = diagonal hit. The
// response is aggregated over all touched bricks so a seam hit applies the
// flip exactly once per axis (two `vy` flips would cancel out and let the
// ball through).
const pens = hits.map((b) => {
  const xPen = Math.min(sx + r, b.x + b.w) - Math.max(sx - r, b.x);
  const yPen = Math.min(sy + r, b.y + b.h) - Math.max(sy - r, b.y);
  return { brick: b, xPen, yPen };
});
let flipVx = false;
let flipVy = false;
for (const p of pens) {
  if (p.xPen <= p.yPen) flipVx = true; // side face hit
  if (p.yPen <= p.xPen) flipVy = true; // top/bottom face hit
}

const vx0 = ball.vx;
const vy0 = ball.vy;
if (flipVx) ball.vx = -vx0;
if (flipVy) ball.vy = -vy0;

// Push out: on each flipped axis, snap the ball back just outside the brick
// whose face was hit (the smallest penetration on that axis). If that still
// overlaps another touched brick (deep seam graze), extend the snap until
// every touched brick is clear — otherwise the next frame re-triggers the
// bounce forever (sticky bounce). The direction follows the pre-bounce
// velocity: the ball entered through the face it was coming from.
if (flipVy) {
  const b = pens.reduce((m, p) => (p.yPen < m.yPen ? p : m)).brick;
  ball.y = vy0 > 0 ? b.y - r : b.y + b.h + r;
  if (pens.some((p) => overlapsAt(ball.x, ball.y, r, p.brick))) {
    ball.y = vy0 > 0
      ? Math.min(...pens.map((p) => p.brick.y)) - r
      : Math.max(...pens.map((p) => p.brick.y + p.brick.h)) + r;
  }
}
if (flipVx) {
  const b = pens.reduce((m, p) => (p.xPen < m.xPen ? p : m)).brick;
  ball.x = vx0 > 0 ? b.x - r : b.x + b.w + r;
  if (pens.some((p) => overlapsAt(ball.x, ball.y, r, p.brick))) {
    ball.x = vx0 > 0
      ? Math.min(...pens.map((p) => p.brick.x)) - r
      : Math.max(...pens.map((p) => p.brick.x + p.brick.w)) + r;
  }
}

