// Creates a fresh game state.
export function createState(level = 1) {
  const speed = ballSpeed(level);
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -speed },
    bricks: makeBricks(level),
  };
  // Previous-frame position, used by `brickHit()` to sweep the ball's path
  // (see tunnelling, ISSUES.md #1). Set on every `step()`.
  state.ball.px = state.ball.x;
  state.ball.py = state.ball.y;
  return state;
}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision resolution (ISSUES.md #1) ------------------------------

// Coarsest sub-step allowed when sweeping the ball's path. The ball is 14 px
// across, so a sub-step under its diameter can never skip a brick (a brick is
// only 20 px tall; crossing it top-to-bottom needs 34 px = BRICK_H + diameter,
// against 35.5 px for a capped 50 ms frame at level 6). Staying at 2 px also
// keeps face detection honest at seams: the 8 px grid gap lets the ball
// straddle two bricks with at most 3 px of horizontal overlap, so a sub-step
// below that still classifies a straight-down seam shot as a top hit.
const SWEEP_STEP = 2;

// True if the ball (box-approximated, centered at x/y) overlaps the brick.
// Same AABB test as `collides`, but for a swept sample position rather than
// the ball object itself.
function overlapsAt(x, y, r, brick) {
  return (
    x + r > brick.x &&
    x - r < brick.x + brick.w &&
    y + r > brick.y &&
    y - r < brick.y + brick.h
  );
}

// Resolves one pass of ball/brick collisions: destroys every brick the ball
// touches and bounces the ball off the FIRST contact along its path.
//
// - per-face: the axis with the *smaller* penetration is the face that was
//   hit — flip `vy` on a top/bottom hit, `vx` on a side hit, and leave the
//   other component exactly as it was;
// - corner: equal penetrations mean a diagonal hit — flip both components;
// - push out: the ball is repositioned outside the brick rectangle, so the
//   next frame cannot re-trigger the bounce (no sticky bounce);
// - neighbours: the 8 px grid gap is narrower than the 14 px ball, so every
//   seam overlaps two bricks in the SAME pass — the aggregate response is
//   applied exactly once per axis (two `vy` flips would cancel out and let
//   the ball through);
// - tunnelling: detection is discrete (position before / after the move), and
//   at level 6 a capped frame moves 35.5 px against the 34 px needed to cross
//   a brick — so the path from the previous position (`ball.px`/`ball.py`) to
//   the current one is swept in sub-steps.
//
// Returns the list of destroyed bricks.
export function brickHit(ball, bricks) {
  const r = ball.r;
  const live = bricks.filter((b) => b.alive !== false);
  if (live.length === 0) return [];

  // Start of the sweep: the previous frame's position when known, otherwise
  // the current one (single-position detection, no sweep).
  const x0 = Number.isFinite(ball.px) ? ball.px : ball.x;
  const y0 = Number.isFinite(ball.py) ? ball.py : ball.y;
  const dx = ball.x - x0;
  const dy = ball.y - y0;
  const dist = Math.hypot(dx, dy);
  const sub = Math.max(1, Math.ceil(dist / SWEEP_STEP));

  // First sample along the path where the ball touches any brick. This is the
  // true impact point — everything beyond it is unreachable this frame.
  let sx = ball.x;
  let sy = ball.y;
  let hits = [];
  for (let i = 0; i <= sub; i++) {
    const t = i / sub;
    const px = x0 + dx * t;
    const py = y0 + dy * t;
    hits = live.filter((b) => overlapsAt(px, py, r, b));
    if (hits.length > 0) {
      sx = px;
      sy = py;
      break;
    }
  }
  if (hits.length === 0) return [];

  // Face detection: for each touched brick, the smaller penetration is the
  // face that was hit. Equal penetration on both axes = diagonal hit. The
  // response is aggregated over all touched bricks so a seam hit applies the
  // flip exactly once per axis (two `vy` flips would cancel out and let the
  // ball through).
  const pens = hits.map((b) => {
    const xPen = Math.min(sx + r, b.x + b.w) - Math.max(sx - r, b.x);
    const yPen = Math.min(sy + r, b.y + b.h) - Math.max(sy - r, b.y);
    return { brick: b, xPen, yPen };
  });
