export function createState(level = 1) {
  const speed = ballSpeed(level);
  // The ball remembers its previous-frame position (`px`/`py`), used by
  // `brickHit()` to sweep the ball's path between the two discrete positions
  // (tunnelling, see ISSUES.md #1). `step()` updates them every frame.
  const ball = {
    x: WIDTH / 2,
